function initBlogIndex2(){const isDarkMode=typeof window.__isDarkMode!=='undefined'?window.__isDarkMode:localStorage.getItem('darkMode')!=='false';if(!document.body.classList.contains('dark')&&!document.body.classList.contains('light')){document.body.classList.toggle("light",!isDarkMode);document.body.classList.toggle("dark",isDarkMode);}
const toggleCheckbox=document.getElementById("toggle");if(toggleCheckbox)toggleCheckbox.checked=isDarkMode;applyDarkModeStyles(isDarkMode);if(typeof window.updateGridTheme==='function')window.updateGridTheme(isDarkMode);document.querySelectorAll('[data-bg]').forEach(el=>{el.style.backgroundImage=`url('${el.dataset.bg}')`;});}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initBlogIndex2);}else{initBlogIndex2();}
function toggleStyles(event){if(event)event.preventDefault();const isDark=document.body.classList.contains("dark");const newMode=!isDark;document.body.classList.toggle("dark",newMode);document.body.classList.toggle("light",!newMode);localStorage.setItem("darkMode",newMode);const toggleCheckbox=document.getElementById("toggle");if(toggleCheckbox)toggleCheckbox.checked=newMode;applyDarkModeStyles(newMode);if(typeof window.updateGridTheme==='function')window.updateGridTheme(newMode);}
function applyDarkModeStyles(isDarkMode){const body=document.body;body.style.backgroundColor="";};